import csv
from datetime import datetime

def stream_group_actions_by_user(file_path, batch_size=1000):
    allowed = {'login', 'click', 'purchase'}
    batch = {}
    bad = 0
    with open(file_path, newline='') as f:
        reader = csv.reader(f)
        for i, row in enumerate(reader, 1):
            if len(row) != 4:
                bad += 1
                continue
            ts, user, action, value = row
            try:
                ts_dt = datetime.fromisoformat(ts)
                if user == '' or action not in allowed:
                    bad += 1
                    continue
                value_f = float(value)
            except Exception:
                bad += 1
                continue
            rec = {'timestamp': ts_dt.isoformat(), 'action': action, 'value': value_f}
            batch.setdefault(user, []).append(rec)
            if i % batch_size == 0:
                yield {u: list(recs) for u, recs in batch.items()}
                batch.clear()
    if batch:
        yield {u: list(recs) for u, recs in batch.items()}
```

## Follow-up Questions
- How would you add per-user backpressure when the sink is slow?
- How would you adjust for out-of-order timestamps within a batch?

## Why This Is Asked
Tests practical streaming with Python basics: IO handling, lightweight typing, error resilience, and bounded memory.

## Key Concepts
- Generators and streaming IO
- TypedDict for lightweight schema
- Real-time aggregation with bounded memory
- Error handling and metrics

## Code Example
```python
from typing import TypedDict, Iterator, Dict
import json

class LogLine(TypedDict):
    level: str
    ts: int
    msg: str

def process_logs(stream: Iterator[str], batch_size: int = 50):
    counts: Dict[str, int] = {}
    total = 0
    errors = 0
    for line in stream:
        total += 1
        try:
            data = json.loads(line)
            if not isinstance(data, dict) or not all(k in data for k in ("level", "ts", "msg")):
                raise ValueError("Invalid keys")
            log: LogLine = {"level": str(data["level"]), "ts": int(data["ts"]), "msg": str(data["msg"])}
            counts[log["level"]] = counts.get(log["level"], 0) + 1
        except Exception:
            errors += 1
        if total % batch_size == 0:
            yield {"counts": counts.copy(), "total": total, "errors": errors}
    if total % batch_size != 0:
        yield {"counts": counts, "total": total, "errors": errors}
```

## Follow-up Questions
- How would you extend this to handle out-of-order lines with timestamps? 
- How would you benchmark latency between input and snapshots?
